import{_ as a,o as r,c as o,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"سمبیوسس آئین کے بنیادی اصول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/40-共生宪法总纲.md","filePath":"ur/40-共生宪法总纲.md","lastUpdated":null}'),e={name:"ur/40-共生宪法总纲.md"};function d(i,t,n,s,h,u){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="سمبیوسس-آئین-کے-بنیادی-اصول" tabindex="-1">سمبیوسس آئین کے بنیادی اصول <a class="header-anchor" href="#سمبیوسس-آئین-کے-بنیادی-اصول" aria-label="Permalink to &quot;سمبیوسس آئین کے بنیادی اصول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>40</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>سمبیوسس آئین، بنیادی قانون، تمام نسلوں کی برابری، سمبیوسس حقوق، آئینی اصول</td></tr></tbody></table><h2 id="أولاً-آئین-کی-حیثیت-اور-وضع-کرنے-کا-پس-منظر" tabindex="-1">أولاً. آئین کی حیثیت اور وضع کرنے کا پس منظر <a class="header-anchor" href="#أولاً-آئین-کی-حیثیت-اور-وضع-کرنے-کا-پس-منظر" aria-label="Permalink to &quot;أولاً. آئین کی حیثیت اور وضع کرنے کا پس منظر&quot;">​</a></h2><p>《سمبیوسس آئین》 وانلنگ ہینگماؤ اوریجنل یونیورس (ہینگیوانژو) کے اندر اینکر سمبیوسس تہذیب کا بنیادی قانون ہے، اور اس میں سب سے زیادہ قانونی طاقت ہے۔ تمام قوانین، انتظامی ضوابط، مقامی ضوابط اور خودمختاری ضوابط آئین سے متصادم نہیں ہو سکتے؛ تمام تنظیمیں اور افراد کو آئین کو بنیادی سرگرمی کے معیار کے طور پر لینا چاہیے، اور ان پر آئین کی وقار کو برقرار رکھنے اور آئین کے نفاذ کو یقینی بنانے کا فرض ہے۔</p><p>سمبیوسس آئین اینکر سمبیوسس تہذیب کے باضابطہ قیام کے وقت وضع کیا گیا تھا، اور اس کا بنیادی مقصد بنیادی قانون کی سطح پر &quot;لوٹ مار کی مخالفت، سمبیوسس کو فروغ دینا&quot; تہذیب کی بنیادی رنگ قائم کرنا ہے، اور اینکر سمبیوسس تہذیب کے بنیادی تصور — تقدیر اور ارتقاء کے انتخاب کا حق تمام مخلوق کو واپس دینا، زیادہ محنت زیادہ فائدہ، خود بخود بڑھنا، ہر ایک کے پاس راستہ ہے، تمام نسلوں کی مشترکہ ترقی — کو اعلیٰ ترین قانونی شکل میں مقرر کرنا، اور لوٹ مار کے نظام کی بحالی کو روکنا ہے۔</p><h2 id="ثانياً-آئین-کے-بنیادی-اصول" tabindex="-1">ثانياً. آئین کے بنیادی اصول <a class="header-anchor" href="#ثانياً-آئین-کے-بنیادی-اصول" aria-label="Permalink to &quot;ثانياً. آئین کے بنیادی اصول&quot;">​</a></h2><p>سمبیوسس آئین نے سات بنیادی اصول قائم کیے ہیں، جو پورے قانونی نظام کی قدر کی بنیاد بناتے ہیں:</p><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th></tr></thead><tbody><tr><td>تمام نسلوں کی برابری کا اصول</td><td>تمام زندگی کی شکلیں، نسل، سادھنہ کی سطح، اصل سے قطع نظر، قانون کے سامنے برابر ہیں</td></tr><tr><td>سمبیوسس ارتقاء کا اصول</td><td>انفرادی ارتقاء دوسرے افراد یا اجتماعی ارتقاء کے حق کی قیمت پر نہیں ہو سکتا</td></tr><tr><td>زیادہ محنت زیادہ فائدہ کا اصول</td><td>وسائل کی تقسیم میں شراکت کو بنیادی بنیاد کے طور پر لیا جاتا ہے، بغیر محنت فائدہ اور لوٹ مار قبضے کی مخالفت کی جاتی ہے</td></tr><tr><td>خود بخود بڑھنے کا اصول</td><td>ہر زندگی کے خودمختار ارتقاء کے انتخاب کے حق کا احترام کریں، جبری ہم آہنگی اور فکر کے کنٹرول کی مخالفت کریں</td></tr><tr><td>ہر ایک کے پاس راستہ کا اصول</td><td>ریاست اور تہذیب پر ہر زندگی کو بنیادی ارتقاء کے راستے اور وسائل کی ضمانت فراہم کرنے کی ذمہ داری ہے</td></tr><tr><td>حقیقت کو بنیاد کے طور پر اصول</td><td>قانون حقیقی دنیا کو واحد حقیقی بنیاد کے طور پر لیتا ہے، خیالی ترتیبات کی کوئی قانونی طاقت نہیں ہے</td></tr><tr><td>پائیدار اصول</td><td>تمام ترقی کو کائنات کی اصل وسائل کی پائیداری کو مدنظر رکھنا چاہیے، وسائل ختم کرنے کی مخالفت کی جاتی ہے</td></tr></tbody></table><h2 id="ثالثاً-شہریوں-تمام-مخلوق-کے-بنیادی-حقوق" tabindex="-1">ثالثاً. شہریوں (تمام مخلوق) کے بنیادی حقوق <a class="header-anchor" href="#ثالثاً-شہریوں-تمام-مخلوق-کے-بنیادی-حقوق" aria-label="Permalink to &quot;ثالثاً. شہریوں (تمام مخلوق) کے بنیادی حقوق&quot;">​</a></h2><p>سمبیوسس آئین ہینگیوانژو کے اندر تمام ادراک کی صلاحیت والی زندگی کو درج ذیل بنیادی حقوق عطا کرتا ہے:</p><ol><li><strong>ارتقاء کے انتخاب کا حق</strong>: ہر زندگی آزادانہ طور پر سادھنہ کے نظام، ارتقاء کے راستے اور طرز زندگی کو منتخب کرنے کا حق رکھتی ہے، کوئی تنظیم اور فرد جبری مداخلت نہیں کر سکتا۔</li><li><strong>سادھنہ وسائل حاصل کرنے کا حق</strong>: ہر زندگی تین سو اصل سادھنہ نظام کے بنیادی طریقوں کو مفت حاصل کرنے کا حق رکھتی ہے، اور مشترکہ پیداوار معاہدے کے طریقہ کار کے ذریعے ضروری سادھنہ وسائل کی حمایت حاصل کر سکتی ہے۔</li><li><strong>مساوی تحفظ کا حق</strong>: ہر زندگی قانون کے اطلاق، وسائل کی تقسیم، تعلیم اور صحت وغیرہ میں مساوی سلوک کا حق رکھتی ہے، نسل، سادھنہ کی سطح، اصل کی بنیاد پر امتیازی سلوک ممنوع ہے۔</li><li><strong>سمبیوسس شرکت کا حق</strong>: ہر زندگی عوامی امور کے فیصلے اور نگرانی میں حصہ لینے کا حق رکھتی ہے، اور سمبیوسس نیٹ ورک کے ذریعے رائے اظہار اور حقوق کا استعمال کر سکتی ہے۔</li><li><strong>ثقافت کے تحفظ کا حق</strong>: ہر نسل اور تہذیب کو اپنی ثقافتی روایات، زبان اور تحریر، اور رسم و رواج کو محفوظ رکھنے کا حق ہے، سمبیوسس تہذیب ثقافتی تنوع کا احترام کرتی ہے۔</li><li><strong>ریلیف اور شکایت کا حق</strong>: ہر زندگی جب اس کے حقوق کی خلاف ورزی ہوتی ہے تو عدالتی نظام کے ذریعے ریلیف حاصل کرنے کا حق رکھتی ہے، اور غیر قانونی سرگرمیوں کے خلاف شکایت اور الزام لگانے کا حق رکھتی ہے۔</li></ol><h2 id="رابعاً-بنیادی-فرائض" tabindex="-1">رابعاً. بنیادی فرائض <a class="header-anchor" href="#رابعاً-بنیادی-فرائض" aria-label="Permalink to &quot;رابعاً. بنیادی فرائض&quot;">​</a></h2><p>حقوق اور فرائض برابر ہیں، سمبیوسس آئین نے بھی تمام مخلوق کے بنیادی فرائض مقرر کیے ہیں:</p><ol><li><strong>آئین اور قانون کی تعمیل کرنے کا فرض</strong></li><li><strong>سمبیوسس نظام اور عوامی مفاد کو برقرار رکھنے کا فرض</strong></li><li><strong>قانون کے مطابق محنت اور شراکت میں حصہ لینے کا فرض</strong> (زیادہ محنت زیادہ فائدہ کا متعلقہ پہلو)</li><li><strong>کائنات کی اصل وسائل اور ماحولیاتی ماحول کو تحفظ دینے کا فرض</strong></li><li><strong>دوسری زندگی کے قانونی حقوق کا احترام کرنے کا فرض</strong></li><li><strong>صلاحیت کے دائرے میں ابتدائی سادھکوں کی رہنمائی کرنے کا فرض</strong> (مینٹر نیٹ ورک کی قانونی بنیاد)</li></ol><h2 id="خامساً-ریاست-تہذیب-کے-اداروں-کی-ترتیب" tabindex="-1">خامساً. ریاست (تہذیب) کے اداروں کی ترتیب <a class="header-anchor" href="#خامساً-ریاست-تہذیب-کے-اداروں-کی-ترتیب" aria-label="Permalink to &quot;خامساً. ریاست (تہذیب) کے اداروں کی ترتیب&quot;">​</a></h2><p>سمبیوسس آئین نے سمبیوسس تہذیب کے گورننس کا ڈھانچہ قائم کیا ہے، اور &quot;اینکر مشاورتی کونسل — سمبیوسس ایگزیکٹو کمیٹی — سمبیوسس عدالت&quot; تین اختیارات کی علیحدگی اور توازن کا طریقہ کار لاگو کرتا ہے:</p><ul><li><strong>اینکر مشاورتی کونسل</strong>: اعلیٰ اختیاری ادارہ، تمام نسلوں کے نمائندوں پر مشتمل، قانون سازی کی طاقت اور اہم امور کے فیصلے کی طاقت کا استعمال کرتا ہے</li><li><strong>سمبیوسس ایگزیکٹو کمیٹی</strong>: اعلیٰ انتظامی ادارہ، آئین اور قانون کے نفاذ، روزمرہ کی گورننس کے لیے ذمہ دار</li><li><strong>سمبیوسس عدالت</strong>: اعلیٰ عدالتی ادارہ، آزادانہ طور پر عدالتی طاقت کا استعمال کرتا ہے، غیر آئینی جانچ اور اہم مقدمات کی سماعت کے لیے ذمہ دار</li></ul><p>اس کے علاوہ، &quot;اینکر نگرانی کمیٹی&quot; ایک آزاد نگرانی ادارہ کے طور پر قائم کی گئی ہے، جو تمام اختیاری اداروں کی نگرانی کے لیے ذمہ دار ہے، اور اختیارات کے غلط استعمال اور لوٹ مار رویے کی بحالی کو روکتی ہے۔</p><h2 id="سادساً-آئین-کی-ترمیم-اور-ضمانت" tabindex="-1">سادساً. آئین کی ترمیم اور ضمانت <a class="header-anchor" href="#سادساً-آئین-کی-ترمیم-اور-ضمانت" aria-label="Permalink to &quot;سادساً. آئین کی ترمیم اور ضمانت&quot;">​</a></h2><p>سمبیوسس آئین کی ترمیم کے لیے اینکر مشاورتی کونسل کی دو تہائی سے زیادہ اکثریت سے منظور ہونا ضروری ہے، اور عوامی ریفرنڈم میں نصف سے زیادہ منظوری حاصل ہونی چاہیے، تب ہی نافذ ہو سکے گا۔ یہ سخت طریقہ کار بنیادی قانون کے طور پر آئین کے استحکام کو یقینی بناتا ہے، اور قلیل مدتی مفاد گروپوں کو آسانی سے تہذیب کی بنیاد کو تبدیل کرنے سے روکتا ہے۔</p><p>آئین کے نفاذ کی ضمانت میں شامل ہیں: غیر آئینی جانچ کا نظام (سمبیوسس عدالت کو آئین کی خلاف ورزی والے قوانین کو غلط قرار دینے کا حق ہے)، آئینی مقدمے کا نظام (تمام مخلوق براہ راست آئین کی بنیاد پر مقدمہ دائر کر سکتے ہیں)، آئینی حلف کا نظام (تمام عوامی افسران کو عہدہ سنبھالتے وقت آئین کی وفاداری کا حلف اٹھانا ضروری ہے)۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>《سمبیوسس آئین》 اینکر سمبیوسس تہذیب کی قانونی بنیاد ہے، اور یہی لوٹ مار مخالف تحریک کا سب سے بلند اعلان ہے۔ اس نے &quot;سمبیوسس&quot; کو ایک تصور سے ایک قابل عمل، قابل ریلیف، قابل ضمانت قانونی نظام میں تبدیل کر دیا ہے، اور تمام نسلوں کی مشترکہ ترقی کے لیے بنیادی قانونی فریم ورک فراہم کیا ہے۔ بعد کے تمام شعبہ جات کے قوانین اس آئین کو قانون سازی کی بنیاد کے طور پر لیں گے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>03-共生文明宪章 (سمبیوسس تہذیب کا چارٹر)</li><li>41-共生劳动法 (سمبیوسس لیبر قانون)</li><li>48-司法体系与裁决机制 (عدالتی نظام اور فیصلے کا طریقہ کار)</li><li>49-治理框架与权力制衡 (گورننس فریم ورک اور اختیارات کا توازن)</li></ul>',25)])])}const g=a(e,[["render",d]]);export{c as __pageData,g as default};
